import {ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';

describe('ToolRegistry schema compilation and caching', () => {
  it('throws synchronously at register time naming the tool when a static inputSchema is invalid JSON Schema', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'bad_schema_tool',
          description: 'Invalid schema',
          inputSchema: {
            type: 'object',
            properties: {query: {type: 'unknown-type'}},
          },
        },
        async () => 'ok'
      )
    ).toThrow(/bad_schema_tool/);
  });

  it('compiles a static inputSchema once at register time without re-reading definition.inputSchema on execute', async () => {
    const registry = new ToolRegistry();
    let schemaReads = 0;
    const schema = {
      type: 'object',
      properties: {city: {type: 'string'}},
      required: ['city'],
    };
    const definition: ToolDefinition = {
      name: 'lookup_city',
      description: 'Look up a city',
      get inputSchema() {
        schemaReads += 1;
        return schema;
      },
    };

    registry.register(definition, async input => `found ${String(input.city)}`);
    const readsAtRegister = schemaReads;
    const first = await registry.execute('lookup_city', {city: 'Amsterdam'});
    const second = await registry.execute('lookup_city', {city: 'Rotterdam'});

    expect({
      readsAtRegister,
      readsAfterExecutes: schemaReads,
      firstResult: first.result,
      secondResult: second.result,
    }).toEqual({
      readsAtRegister: 1,
      readsAfterExecutes: 1,
      firstResult: 'found Amsterdam',
      secondResult: 'found Rotterdam',
    });
  });
});

