import Ajv from 'ajv';
import type {ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId?: string;
  sessionId?: string;
  workspaceId?: string;
  authHeaders?: Record<string, string>;
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

/** Either a static ToolDefinition or a function that returns one dynamically per call. */
export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinitionSource;
  executor: ToolExecutor;
  validate?: ValidateFunction;
}

export function normalizeToolResponse(raw: string | ToolResponse): ToolResponse {
  if (typeof raw === 'string') return {result: raw};
  return raw;
}

function resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
  return typeof source === 'function' ? source() : source;
}

function compileSchema(ajv: Ajv.Ajv, toolName: string, schema: Record<string, unknown>): ValidateFunction {
  try {
    return ajv.compile(schema);
  } catch (error) {
    const detail = error instanceof Error ? error.message : String(error);
    throw new Error(`Invalid inputSchema for tool "${toolName}": ${detail}`);
  }
}

export class ToolRegistry {
  private tools = new Map<string, RegisteredTool>();
  private ajv = new Ajv({strict: false, validateFormats: false, allErrors: true});
  private dynamicValidators = new WeakMap<Record<string, unknown>, ValidateFunction>();

  register(definition: ToolDefinitionSource, executor: ToolExecutor): void {
    const resolved = resolveDefinition(definition);
    const validate =
      typeof definition === 'function' ? undefined : compileSchema(this.ajv, resolved.name, resolved.inputSchema);
    this.tools.set(resolved.name, {definition, executor, validate});
  }

  getValidator(tool: RegisteredTool): ValidateFunction {
    if (tool.validate) return tool.validate;
    const resolved = resolveDefinition(tool.definition);
    const schema = resolved.inputSchema;
    const cached = this.dynamicValidators.get(schema);
    if (cached) return cached;
    const compiled = compileSchema(this.ajv, resolved.name, schema);
    this.dynamicValidators.set(schema, compiled);
    return compiled;
  }

